//! One checked archive for all built-in app documents. Runtime/transport state stays local.
use crate::{Result,library_backup::{Blob,Plan}};
use serde_json::{json,Value};
use std::{collections::{BTreeMap,BTreeSet},path::Path};
const KINDS:[&str;8]=["files","notes","annotation","rss","reader","browser","youtube","walkie"];
fn data(root:&Path,k:&str)->Result<std::path::PathBuf>{crate::sdk::scope(root,match k{"annotation"=>"app.onklav.annotation","rss"=>"app.onklav.rss","reader"=>"app.onklav.reader","browser"=>"app.onklav.browser","youtube"=>"app.onklav.youtube",_=>"app.onklav.walkie"})}
fn notes(root:&Path,op:&str,v:&Value)->Result<Value>{if op=="export"{crate::content::notes_backup(root,op,"")?;let p=root.join("notes-backup-export.json");let result=(||{serde_json::from_slice(&crate::sdk::read_bounded(&p,16*1024*1024)?).map_err(|_|"Invalid Notes backup".into())})();let _=std::fs::remove_file(p);return result}
 let p=root.join("notes-backup-import.json");crate::sdk::atomic(&p,&serde_json::to_vec(v).map_err(|e|e.to_string())?)?;let result=(||{let review=crate::content::notes_backup(root,"inspect","")?;if op=="restore"{crate::content::notes_backup(root,"restore",review["sha256"].as_str().unwrap())}else{Ok(review)}})();let _=std::fs::remove_file(p);result
}
pub(crate) fn walkie_export(root:&Path)->Result<Value>{Ok(json!({"preferences":crate::walkie_store::backup_export(root)?,"archive":crate::walkie_clips::backup_export(root)?}))}
pub(crate) fn walkie_plan(root:&Path,v:&Value)->Result<Plan>{let obj=v.as_object().filter(|o|o.len()==2&&o.contains_key("preferences")&&o.contains_key("archive")).ok_or("Invalid Walkie backup")?;let(n,k,size)=crate::walkie_store::backup_plan(root,&obj["preferences"])?;let(c,d,bytes)=crate::walkie_clips::backup_plan(root,&obj["archive"])?;
 let old_p=root.join("walkie.json");let old_a=root.join("walkie-clips.json");let mut other=crate::sdk::private_size(root,&old_p)?;if old_a.exists(){other=other.saturating_sub(std::fs::metadata(&old_a).map_err(|e|e.to_string())?.len());}if other+size+bytes>16*1024*1024{return Err("Restored Walkie data exceeds storage limit".into())}Ok(Plan{new:n+c,kept:k+d,targets:BTreeMap::new()})}
pub(crate) fn walkie_commit(host:&Path,root:&Path,v:&Value)->Result<()>{walkie_plan(root,v)?;crate::library_backup::check(host)?;crate::walkie_store::backup_commit(root,&v["preferences"])?;crate::library_backup::check(host)?;crate::walkie_clips::backup_commit(root,&v["archive"])}
pub(crate) fn export(root:&Path)->Result<(Value,BTreeMap<String,std::path::PathBuf>)>{let(files,mut paths)=crate::content::backup::export(root)?;let(images,images_paths)=crate::drawing::backup_export(&data(root,"annotation")?)?;paths.extend(images_paths);if root.join("vault.bin.bak").exists()||root.join("vault.bin.new").exists(){return Err("Open and close Vault to complete its save before backup".into())}let vault=root.join("vault.bin");let has_vault=vault.try_exists().map_err(|e|e.to_string())?;if has_vault{vault_file(&vault)?;paths.insert("vault/document.bin".into(),vault);}Ok((json!({"vault":has_vault,"files":files,"notes":notes(root,"export",&Value::Null)?,"annotation":images,"rss":crate::feeds::backup_export(&data(root,"rss")?)?,"reader":crate::reader_backup::export(&data(root,"reader")?)?,"browser":crate::browser::backup_export(&data(root,"browser")?)?,"youtube":crate::videos::backup_export(&data(root,"youtube")?)?,"walkie":walkie_export(&data(root,"walkie")?)?}),paths))}
fn payloads(blobs:&BTreeMap<String,Blob>,prefix:&str)->BTreeMap<String,Blob>{blobs.iter().filter(|(k,_)|k.starts_with(prefix)).map(|(k,b)|(k.clone(),Blob{bytes:b.bytes,sha256:b.sha256.clone()})).collect()}
pub(crate) fn plan(root:&Path,v:&Value,blobs:&BTreeMap<String,Blob>)->Result<Plan>{let o=v.as_object().ok_or("Invalid app documents backup")?;if o.len()!=KINDS.len()+usize::from(o.contains_key("vault"))||o.get("vault").is_some_and(|v|!v.is_boolean())||KINDS.iter().any(|k|!o.contains_key(*k)){return Err("Incomplete app documents backup".into())}if blobs.keys().any(|k|!k.starts_with("files/")&&!k.starts_with("images/")&&k!="vault/document.bin"){return Err("Unexpected app backup payload".into())}
 let vault_present=v["vault"].as_bool().unwrap_or(false);if vault_present!=blobs.contains_key("vault/document.bin"){return Err("Vault backup payload mismatch".into())}
 let file_ids:BTreeSet<_>=v["files"].as_array().ok_or("Invalid file records")?.iter().filter_map(|r|r["id"].as_str()).collect();if v["notes"]["notes"].as_array().ok_or("Invalid note records")?.iter().any(|n|n["id"].as_str().is_some_and(|id|file_ids.contains(id))){return Err("Conflicting note/file identity".into())}
 let mut p=crate::content::backup::plan(root,&v["files"],&payloads(blobs,"files/"))?;let note=notes(root,"inspect",&v["notes"])?;crate::content::backup::combined_capacity(root,p.new+note["new"].as_u64().unwrap() as usize)?;p.new+=note["new"].as_u64().unwrap() as usize;p.kept+=note["kept"].as_u64().unwrap() as usize;
 for k in ["annotation","rss","reader","browser","youtube","walkie"]{crate::library_backup::check(root)?;let d=data(root,k)?;let next=match k{"annotation"=>crate::drawing::backup_plan(&d,&v[k],&payloads(blobs,"images/"))?,"rss"=>crate::feeds::backup_plan(&d,&v[k])?,"reader"=>crate::reader_backup::plan(&d,&v[k])?,"browser"=>crate::browser::backup_plan(&d,&v[k])?,"youtube"=>crate::videos::backup_plan(&d,&v[k])?,_=>walkie_plan(&d,&v[k])?};p.new+=next.new;p.kept+=next.kept;p.targets.extend(next.targets);}
 if vault_present{let target=root.join("vault.bin");if target.try_exists().map_err(|e|e.to_string())?{vault_file(&target)?;p.kept+=1;}else{if root.join("vault.bin.bak").exists()||root.join("vault.bin.new").exists(){return Err("Open Vault to finish its save recovery before restoring".into())}let b=&blobs["vault/document.bin"];if b.bytes>8_100_000||b.bytes<100{return Err("Invalid Vault backup size".into())}p.targets.insert("vault/document.bin".into(),target);p.new+=1;}}
 Ok(p)}
pub(crate) fn commit(root:&Path,v:&Value,blobs:&BTreeMap<String,Blob>)->Result<()>{plan(root,v,blobs)?;crate::content::backup::commit(root,&v["files"],&payloads(blobs,"files/"))?;notes(root,"restore",&v["notes"])?;for k in ["annotation","rss","reader","browser","youtube","walkie"]{crate::library_backup::check(root)?;let d=data(root,k)?;match k{"annotation"=>crate::drawing::backup_commit(root,&d,&v[k],&payloads(blobs,"images/"))?,"rss"=>crate::feeds::backup_commit(root,&d,&v[k])?,"reader"=>crate::reader_backup::commit(root,&d,&v[k])?,"browser"=>crate::browser::backup_commit(root,&d,&v[k])?,"youtube"=>crate::videos::backup_commit(root,&d,&v[k])?,_=>walkie_commit(root,&d,&v[k])?}}Ok(())}
// Vault is an opaque password-encrypted payload, never a Files entry.
fn vault_file(path:&Path)->Result<()>{use std::io::Read;let m=std::fs::symlink_metadata(path).map_err(|e|e.to_string())?;if !m.is_file()||m.len()<100||m.len()>8_100_000{return Err("Invalid Vault file".into())}let mut h=[0u8;40];std::fs::File::open(path).and_then(|mut f|f.read_exact(&mut h)).map_err(|e|e.to_string())?;if &h[..8]!=b"OKVAULT1"||&h[8..]!=b"6f6e6b6c61767661756c74646f637631"{return Err("Invalid Vault header".into())}Ok(())}
#[cfg(test)]mod tests{use super::*;use std::fs;
 fn request(root:&Path,op:&str,sha:&str)->Result<Value>{let d=data(root,"annotation")?;crate::library_backup::dispatch(root,&d,&json!({"kind":"documents","operation":op,"sha256":sha}))}
 #[test]fn combined_backup_restores_notes_files_and_passive_voice_without_transport_replay(){
  let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();let r=a.path();crate::content::note_save(r,&crate::Note{id:"1".repeat(32),title:"Saved note".into(),text:"Note body".into(),updated:1}).unwrap();fs::write(r.join("content-import.tmp"),"file bytes").unwrap();crate::content::import_staged(r,"documents","Doc.txt","text/plain","user","User",false).unwrap();
  let w=data(r,"walkie").unwrap();crate::walkie_store::service(&w,"walkie.prepare",&json!({"peer":"+15550101234","subscription":7,"label":"Friend"})).unwrap();crate::walkie_clips::host(&w,&crate::walkie_clips::tests::fixture(2,true)).unwrap();
  request(r,"export","").unwrap();fs::copy(r.join("library-backup-export.zip"),b.path().join("library-backup-import.zip")).unwrap();let review=request(b.path(),"inspect","").unwrap();request(b.path(),"restore",review["sha256"].as_str().unwrap()).unwrap();assert_eq!(crate::content::note_list(b.path()).unwrap()[0].text,"Note body");assert_eq!(crate::content::service(b.path(),"library.list",&json!({"folder":"documents"})).unwrap()["total"],2);
  let target=data(b.path(),"walkie").unwrap();let state=crate::walkie_store::service(&target,"walkie.state",&json!({})).unwrap();assert!(state["selected"].is_null());assert_eq!(state["recent"][0]["subscription"],-1);
  let clip=crate::walkie_clips::component(&target,&format!("{:032x}",2),true).unwrap();assert_eq!(clip["restored"],true);assert_eq!(clip["binding"]["subscription"],-1);assert!(!clip["bytes"].as_array().unwrap().is_empty());assert!(crate::walkie_clips::host(&target,&json!({"operation":"attempt","binding":clip["binding"]})).is_err());
  let repeat=request(b.path(),"restore",review["sha256"].as_str().unwrap()).unwrap();assert_eq!(repeat["new"],0);
 }
 #[test]fn encrypted_vault_is_hidden_from_files_and_portable_without_overwriting_existing(){
  let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();let mut opaque=b"OKVAULT1".to_vec();opaque.extend_from_slice(b"6f6e6b6c61767661756c74646f637631");opaque.extend_from_slice(&[93;160]);fs::write(a.path().join("vault.bin"),&opaque).unwrap();
  let listing=crate::content::service(a.path(),"library.list",&json!({"folder":"documents"})).unwrap();assert!(!listing.to_string().contains("vault.bin"));
  request(a.path(),"export","").unwrap();fs::copy(a.path().join("library-backup-export.zip"),b.path().join("library-backup-import.zip")).unwrap();let review=request(b.path(),"inspect","").unwrap();request(b.path(),"restore",review["sha256"].as_str().unwrap()).unwrap();assert_eq!(fs::read(b.path().join("vault.bin")).unwrap(),opaque);
  let mut local=opaque.clone();*local.last_mut().unwrap()=12;fs::write(b.path().join("vault.bin"),&local).unwrap();let review=request(b.path(),"inspect","").unwrap();request(b.path(),"restore",review["sha256"].as_str().unwrap()).unwrap();assert_eq!(fs::read(b.path().join("vault.bin")).unwrap(),local);
 }
 #[test]fn old_backups_without_vault_still_work_and_incomplete_saves_block_export(){let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();let(mut value,paths)=export(a.path()).unwrap();value.as_object_mut().unwrap().remove("vault");assert!(plan(b.path(),&value,&BTreeMap::new()).is_ok());assert!(paths.is_empty());fs::write(a.path().join("vault.bin.new"),b"partial").unwrap();assert!(export(a.path()).is_err());}
 #[test]fn invalid_voice_in_combined_archive_rejects_before_notes_or_files_are_published(){
  let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();let (mut records,paths)=export(a.path()).unwrap();records["walkie"]["archive"]=json!([{"id":"a".repeat(32),"peer":"+15550101234","outgoing":true,"mime":"audio/amr","audio":"00","digest":"0".repeat(64),"millis":400,"created":1}]);assert!(paths.is_empty());assert!(plan(b.path(),&records,&BTreeMap::new()).is_err());assert!(crate::content::note_list(b.path()).unwrap().is_empty());
 }
}
